import { tokenConfig } from '../../auth/tokenConfig';
import { all, call, fork, put, takeEvery } from 'redux-saga/effects';
import axios from 'axios';
import {
    updateManufacturerVariationSuccess,
    updateManufacturerVariationFailed,
    createManufacturerVariationFailed,
    createManufacturerVariationSuccess,
    getManufacturerVariationsFailed,
    getManufacturerVariationsSuccess,
    getManufacturerVariationDetailsSuccess,
    getManufacturerVariationDetailsFailed,
    getManufacturerByIdVariationsSuccess,
    getManufacturerByIdVariationsFailed,
    searchManufacturerVariationsSuccess,
    searchManufacturerVariationsFailed,
    getManufacturerAndProductVariationsSuccess,
    getManufacturerAndProductVariationsFailed,
    searchManufacturerAndProductVariationsSuccess,
    searchManufacturerAndProductVariationsFailed,
} from './actions';
import {
    CREATE_MANUFACTURER_VARIATION,
    UPDATE_MANUFACTURER_VARIATION,
    GET_MANUFACTURER_VARIATIONS,
    GET_MANUFACTURER_VARIATION_DETAILS,
    GET_MANUFACTURER_BY_ID_VARIATIONS,
    SEARCH_MANUFACTURER_VARIATIONS,
    GET_MANUFACTURER_AND_PRODUCT_VARIATIONS,
    SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS,
} from './constants';

//Create wholesale receipt
function* createManufacturerVariation(payload) {
    const apiCall = () => {
        return axios
            .post('manufacturers/variations/create', payload.payload, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);
        yield put(createManufacturerVariationSuccess(response));
    } catch (error) {
        let message;

        console.log('ERRORS', error.response.data);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error;
        }
        yield put(createManufacturerVariationFailed(message, error.response.data.errors));
    }
}

