//Update wholesale variation receipt
function* updateManufacturerVariation(payload) {
    const apiCall = () => {
        return axios
            .patch(`manufacturers/variations/${payload.payload.id}/update`, payload.payload.data, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);

        yield put(updateManufacturerVariationSuccess(response));
    } catch (error) {
        let message;

        console.log('ERRORS', error.response.data);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error.response.data.detail;
        }
        yield put(updateManufacturerVariationFailed(message, error.response.data.errors));
        console.log('Updated Receipt: ', 'Failed');
    }
}

