//RECEIPTS
//Create wholesale receipt
export function* watchCreateManufacturerVariation() {
    yield takeEvery(CREATE_MANUFACTURER_VARIATION, createManufacturerVariation);
}
//Get manufacturer variations for logged in user
export function* watchGetManufacturerVariation() {
    yield takeEvery(GET_MANUFACTURER_VARIATIONS, getManufacturerVariations);
}
//Search manufacturer variations for logged in user
export function* watchSearchManufacturerVariations() {
    yield takeEvery(SEARCH_MANUFACTURER_VARIATIONS, searchManufacturerVariations);
}
//Get  manufacturer by ID  variations
export function* watchGetManufacturerByIdVariation() {
    yield takeEvery(GET_MANUFACTURER_BY_ID_VARIATIONS, getManufacturerByIdVariations);
}
//Update wholesale receipt
export function* watchUpdateManufacturerVariation() {
    yield takeEvery(UPDATE_MANUFACTURER_VARIATION, updateManufacturerVariation);
}

//Get variation details
export function* watchGetManufacturerVariationDetails() {
    yield takeEvery(GET_MANUFACTURER_VARIATION_DETAILS, getManufacturerVariationDetails);
}

//Get manufacturer and product variation details
export function* watchGetManufacturerAndProductVariation() {
    yield takeEvery(GET_MANUFACTURER_AND_PRODUCT_VARIATIONS, getManufacturerAndProductVariations);
}

//Search manufacturer and product variations
export function* watchSearchManufacturerAndProductVariation() {
    yield takeEvery(SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS, searchManufacturerAndProductVariations);
}

function* manufacturerVariationsSaga() {
    yield all([
        fork(watchCreateManufacturerVariation),
        fork(watchGetManufacturerVariation),
        fork(watchSearchManufacturerVariations),
        fork(watchUpdateManufacturerVariation),
        fork(watchGetManufacturerVariationDetails),
        fork(watchGetManufacturerByIdVariation),
        fork(watchGetManufacturerAndProductVariation),
        fork(watchSearchManufacturerAndProductVariation),
    ]);
}

export default manufacturerVariationsSaga;
