import {
    RESET_REDUX,
    CREATE_MANUFACTURER_VARIATION,
    CREATE_MANUFACTURER_VARIATION_SUCCESS,
    CREATE_MANUFACTURER_VARIATION_FAILED,
    UPDATE_MANUFACTURER_VARIATION,
    UPDATE_MANUFACTURER_VARIATION_SUCCESS,
    UPDATE_MANUFACTURER_VARIATION_FAILED,
    SEARCH_MANUFACTURER_VARIATIONS,
    SEARCH_MANUFACTURER_VARIATIONS_SUCCESS,
    SEARCH_MANUFACTURER_VARIATIONS_FAILED,
    GET_MANUFACTURER_VARIATIONS,
    GET_MANUFACTURER_VARIATIONS_SUCCESS,
    GET_MANUFACTURER_VARIATIONS_FAILED,
    GET_MANUFACTURER_BY_ID_VARIATIONS,
    GET_MANUFACTURER_BY_ID_VARIATIONS_SUCCESS,
    GET_MANUFACTURER_BY_ID_VARIATIONS_FAILED,
    GET_MANUFACTURER_VARIATION_DETAILS_FAILED,
    GET_MANUFACTURER_VARIATION_DETAILS_SUCCESS,
    GET_MANUFACTURER_VARIATION_DETAILS,
    GET_MANUFACTURER_AND_PRODUCT_VARIATIONS,
    GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS,
    GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED,
    SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS,
    SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS,
    SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED,
} from './constants';

export const resetRedux = () => ({
    type: RESET_REDUX,
});

export const createManufacturerVariation = (receipt) => ({
    type: CREATE_MANUFACTURER_VARIATION,
    payload: receipt,
});

export const createManufacturerVariationSuccess = (receipts) => ({
    type: CREATE_MANUFACTURER_VARIATION_SUCCESS,
    payload: receipts,
});

export const createManufacturerVariationFailed = (message, errors) => ({
    type: CREATE_MANUFACTURER_VARIATION_FAILED,
    payload: { message: message, errors: errors },
});

//Search distributor variation

export const searchManufacturerVariations = (query, id) => ({
    type: SEARCH_MANUFACTURER_VARIATIONS,
    payload: { query, id },
});
export const searchManufacturerVariationsSuccess = (variations) => ({
    type: SEARCH_MANUFACTURER_VARIATIONS_SUCCESS,
    payload: variations,
});

export const searchManufacturerVariationsFailed = (message, errors) => ({
    type: SEARCH_MANUFACTURER_VARIATIONS_FAILED,
    payload: { message: message, errors: errors },
});

//Get manufacturer variations for logged in user

export const getManufacturerVariations = () => ({
    type: GET_MANUFACTURER_VARIATIONS,
});

export const getManufacturerVariationsSuccess = (variations) => ({
    type: GET_MANUFACTURER_VARIATIONS_SUCCESS,
    payload: variations,
});

export const getManufacturerVariationsFailed = (message, errors) => ({
    type: GET_MANUFACTURER_VARIATIONS_FAILED,
    payload: { message: message, errors: errors },
});

//Get manufacturer by ID variations for any user

export const getManufacturerAndProductVariations = (manufacturer_id, product_id) => ({
    type: GET_MANUFACTURER_AND_PRODUCT_VARIATIONS,
    payload: { manufacturer_id, product_id },
});

export const getManufacturerAndProductVariationsSuccess = (variations) => ({
    type: GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS,
    payload: variations,
});

export const getManufacturerAndProductVariationsFailed = (message, errors) => ({
    type: GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED,
    payload: { message: message, errors: errors },
});

//Search manufacturer and product variations

export const searchManufacturerAndProductVariations = (query, manufacturer_id, product_id) => ({
    type: SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS,
    payload: { query, manufacturer_id, product_id },
});
export const searchManufacturerAndProductVariationsSuccess = (variations) => ({
    type: SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS,
    payload: variations,
});

export const searchManufacturerAndProductVariationsFailed = (message, errors) => ({
    type: SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED,
    payload: { message: message, errors: errors },
});

//Get variations by manufacturer ID and product Id

export const getManufacturerByIdVariations = (id) => ({
    type: GET_MANUFACTURER_BY_ID_VARIATIONS,
    payload: id,
});

export const getManufacturerByIdVariationsSuccess = (variations) => ({
    type: GET_MANUFACTURER_BY_ID_VARIATIONS_SUCCESS,
    payload: variations,
});

export const getManufacturerByIdVariationsFailed = (message, errors) => ({
    type: GET_MANUFACTURER_BY_ID_VARIATIONS_FAILED,
    payload: { message: message, errors: errors },
});

//Update
export const updateManufacturerVariation = (receipt, id) => ({
    type: UPDATE_MANUFACTURER_VARIATION,
    payload: { data: receipt, id: id },
});

export const updateManufacturerVariationSuccess = (receipts) => ({
    type: UPDATE_MANUFACTURER_VARIATION_SUCCESS,
    payload: receipts,
});

export const updateManufacturerVariationFailed = (message, errors) => ({
    type: UPDATE_MANUFACTURER_VARIATION_FAILED,
    payload: { message: message, errors: errors },
});

export const getManufacturerVariationDetails = (id) => ({
    type: GET_MANUFACTURER_VARIATION_DETAILS,
    payload: id,
});
export const getManufacturerVariationDetailsSuccess = (item) => ({
    type: GET_MANUFACTURER_VARIATION_DETAILS_SUCCESS,
    payload: item,
});

export const getManufacturerVariationDetailsFailed = (message, errors) => ({
    type: GET_MANUFACTURER_VARIATION_DETAILS_FAILED,
    payload: { message: message, errors: errors },
});
